def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [x[0] for x in history]
    op = [x[1] for x in history]

    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c
    my_d = sum(1 for x in my if x == 'D')

    last_op = op[-1]
    prev_my = my[-2] if n >= 2 else 'C'

    w = min(8, n)
    rec_op = op[-w:]
    rec_op_c = sum(1 for x in rec_op if x == 'C')
    rec_op_d = w - rec_op_c

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            d_streak += 1
        else:
            break

    c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            c_streak += 1
        else:
            break

    unprov = 0
    for i in range(n):
        if op[i] == 'D':
            if i == 0:
                if my[i] == 'C':
                    unprov += 1
            elif my[i - 1] == 'C':
                unprov += 1

    after_d_punish = 0
    after_d_tolerate = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'D':
                after_d_punish += 1
            else:
                after_d_tolerate += 1

    if after_d_punish == 0 and after_d_tolerate >= 1 and op_c >= op_d and rec_op_d <= 1:
        if n >= 88:
            return 'D'

    if op_d == 0 and after_d_tolerate >= 2 and n >= 80:
        return 'D'

    if op_d == 0 and my_d == 0 and n >= 35 and n < 90:
        if rng.random() < 0.012:
            return 'D'

    if last_op == 'C':
        if op_d > op_c and rec_op_d >= 4 and c_streak <= 1:
            return 'D'
        return 'C'

    if prev_my == 'D':
        if op_c == 0:
            return 'D'
        if op_d > op_c and rec_op_d >= 4 and d_streak >= 4:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'C'

    if unprov == 1 and op_c >= op_d and rec_op_d <= 1 and d_streak <= 1:
        if n >= 97:
            return 'D'
        return 'C'

    if op_c >= op_d and rec_op_d <= 3 and d_streak <= 2:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if rec_op_c >= 2 and c_streak >= 1 and rng.random() < 0.1:
        return 'C'
    return 'D'
